run:
() => {
      const M = window.mehter, out = { songs: 0, cleared: 0, sGrades: 0, score: 0, perfect: 0, good: 0, miss: 0, brk: 0, maxCombo: 0 };
      let seen = -1;
      for (let k = 0; k < 40000; k++) {
        window.mehterSim(0.25);
        if (M.screen !== 'play' && M.screen !== 'results') throw new Error(`gate: unexpected screen ${M.screen} in song ${M.idx}`);
        const r = M.result;
        if (r && M.screen === 'results' && M.idx !== seen) {
          seen = M.idx; out.songs++; if (!r.defeat) out.cleared++; if (r.grade === 'S') out.sGrades++;
          out.score += r.score; out.perfect += r.cnt.perfect; out.good += r.cnt.good; out.miss += r.cnt.miss; out.brk += r.cnt.brk;
          out.maxCombo = Math.max(out.maxCombo, r.maxCombo);
        }
        if (M.autoDone && M.screen === 'results') break;
      }
      if (!M.autoDone) throw new Error(`gate: the bot did not finish (song ${M.idx}, screen ${M.screen})`);
      window.__gateM = out;
    }
